func (f *podFreezer) ei3(p *Resources) (r flatResources) {
	r.FCPURequest = f.codec17(p.CPURequest)
	r.FCPULimit = f.codec17(p.CPULimit)
	r.FMemoryRequest = f.codec17(p.MemoryRequest)
	r.FMemoryLimit = f.codec17(p.MemoryLimit)
	return r
}

func (f *podFreezer) m1(x map[string]string) {
	cnfrt.GrowPool(&f.c0, len(x))
	if len(x) == 0 {
		return
	}
	var keys []string
	cacheLarge := len(x) >= 256
	if cacheLarge {
		keys = make([]string, 0, len(x))
	} else {
		keys = f.k1[:0]
		f.k1 = nil
		if cap(keys) < len(x) {
			keys = make([]string, 0, max(len(x), 2*cap(keys)))
		}
	}
	for k := range x {
		keys = append(keys, k)
	}
	slices.Sort(keys)
	if cacheLarge {
		f.cached1 = append(f.cached1, keys)
	}
	for _, k := range keys {
		f.b.MeasureString(string(k))
		v := x[k]
		f.b.MeasureString(string(v))
	}
	if !cacheLarge {
		f.k1 = keys[:0]
	}
}

func (f *podFreezer) e1(x map[string]string) cnfrt.Span32 {
	if x == nil {
		return cnfrt.NilSpan
	}
	n := len(x)
	if n == 0 {
		return cnfrt.Span32{}
	}
	var keys []string
	reuseBuf := true
	if n >= 256 {
		if f.cachedPos1 >= len(f.cached1) {
			cnfrt.Fail(cnfrt.ErrConcurrentModification)
		}
		keys = f.cached1[f.cachedPos1]
		f.cached1[f.cachedPos1] = nil
		f.cachedPos1++
		if len(keys) != n {
			cnfrt.Fail(cnfrt.ErrConcurrentModification)
		}
		reuseBuf = false
	} else {
		// Take the shared key buffer; a nested map of the same type finds it
		// empty and uses its own.
		keys = f.k1[:0]
		f.k1 = nil
		if cap(keys) < n {
			keys = make([]string, 0, max(n, 2*cap(keys)))
		}
		for k := range x {
			keys = append(keys, k)
		}
		if len(keys) != n {
			cnfrt.Fail(cnfrt.ErrConcurrentModification)
		}
		slices.Sort(keys)
	}
	off := f.reserve(&f.p0, f.c0, n)
	dst := f.s.pool0[off : int(off)+n]
	for i, k := range keys {
		v, ok := x[k]
		if !ok {
			cnfrt.Fail(cnfrt.ErrConcurrentModification)
		}
		dst[i].K = f.b.String(string(k))
		dst[i].V = f.b.String(string(v))
	}
	if reuseBuf {
		f.k1 = keys[:0]
	}
	return cnfrt.Span32{Off: off, Len: uint32(n)}
}

