func (s *PodSnapshot) validate() error {
	v := &podValidator{s: s, cyclic: s.flags&cnfrt.FlagCyclicAllowed != 0, claims: make([]cnfrt.Claims, 5), workBudget: 32*uint64(s.SizeBytes()) + 65536}
	for _, a := range s.zoned {
		v.workBudget += 32 * uint64(len(a.Zone()))
	}
	if s.dict != nil {
		// Strings of an allowed Dict are compared during validation too;
		// their budget stays linear in the dictionary size.
		v.workBudget += min(32*s.dict.Stats().Bytes, 64<<20)
	}
	v.claims[0] = cnfrt.NewClaims(len(s.pool0))
	v.claims[1] = cnfrt.NewClaims(len(s.pool1))
	v.claims[2] = cnfrt.NewClaims(len(s.pool2))
	v.claims[3] = cnfrt.NewClaims(len(s.pool3))
	v.claims[4] = cnfrt.NewClaims(len(s.pool4))
	for i := range s.nodesPod {
		v.row0(&s.nodesPod[i], uint32(i+1))
		if v.err != nil {
			return v.err
		}
	}
	return nil
}

func (s *PodSnapshot) appendSections(secs []cnfrt.Section) []cnfrt.Section {
	if len(s.nodesPod) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionTable, ElemAlign: 8, Tag: 0, Count: uint32(len(s.nodesPod)), Data: cnfrt.ViewSliceLE(s.nodesPod)})
	}
	if len(s.pool0) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 0, Count: uint32(len(s.pool0)), Data: cnfrt.ViewSliceLE(s.pool0)})
	}
	if len(s.pool1) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 1, Count: uint32(len(s.pool1)), Data: cnfrt.ViewSliceLE(s.pool1)})
	}
	if len(s.pool2) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 8, Tag: 2, Count: uint32(len(s.pool2)), Data: cnfrt.ViewSliceLE(s.pool2)})
	}
	if len(s.pool3) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 3, Count: uint32(len(s.pool3)), Data: cnfrt.ViewSliceLE(s.pool3)})
	}
	if len(s.pool4) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 4, Count: uint32(len(s.pool4)), Data: cnfrt.ViewSliceLE(s.pool4)})
	}
	if len(s.strBlob) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionStrBlob, ElemAlign: 1, Count: uint32(len(s.strBlob)), Data: cnfrt.UnsafeStringBytes(s.strBlob)})
	}
	if ext := cnfrt.EncodeExt(s.locEntries, s.zoned); ext != nil {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionExt, ElemAlign: 4, Count: uint32(len(ext)), Data: ext})
	}
	return secs
}

func (s *PodSnapshot) sections() []cnfrt.Section {
	return s.appendSections(make([]cnfrt.Section, 0, 8))
}

func (s *PodSnapshot) header(extra uint32) cnfrt.Header {
	return cnfrt.Header{Flags: s.flags | extra, SchemaHash: SchemaHashPod, HashSeed: s.seed, RootTable: s.rootTable, RootID: s.rootID}
}

// WriteTo writes the snapshot as a .cnf image to w. It returns
// cnfrt.ErrClosed if s is a closed memory-mapped snapshot, or
// cnfrt.ErrDictRequired if s references a process-local cnfrt.Dict.
func (s *PodSnapshot) WriteTo(w io.Writer) (int64, error) {
	if s.mapping != nil && s.mapping.Closed() {
		return 0, cnfrt.ErrClosed
	}
	if s.flags&cnfrt.FlagHasDict != 0 {
		return 0, cnfrt.ErrDictRequired
	}
	var secBuf [8]cnfrt.Section
	n, err := cnfrt.WriteImage(w, s.header(0), s.appendSections(secBuf[:0]))
	runtime.KeepAlive(s)
	return n, err
}

// MarshalCNF returns the snapshot encoded as a .cnf image. It returns
// cnfrt.ErrClosed if s is a closed memory-mapped snapshot, or
// cnfrt.ErrDictRequired if s references a process-local cnfrt.Dict.
func (s *PodSnapshot) MarshalCNF() ([]byte, error) {
	if s.mapping != nil && s.mapping.Closed() {
		return nil, cnfrt.ErrClosed
	}
	if s.flags&cnfrt.FlagHasDict != 0 {
		return nil, cnfrt.ErrDictRequired
	}
	var secBuf [8]cnfrt.Section
	h, secs := s.header(0), s.appendSections(secBuf[:0])
	out, err := cnfrt.AppendImage(make([]byte, 0, cnfrt.ImageSize(h, secs)), h, secs)
	runtime.KeepAlive(s)
	return out, err
}

// WritePodSnapshotAtomic writes s to path atomically (temporary file, fsync, rename,
// directory fsync), so concurrent MapPodFile calls never observe a partial
// file.
func WritePodSnapshotAtomic(path string, s *PodSnapshot) error {
	return cnfrt.WriteSnapshotAtomic(path, func(w io.Writer) error {
		_, err := s.WriteTo(w)
		return err
	})
}

// MapPodFile memory-maps the .cnf file at path read-only and returns a
// snapshot over it. With cnfrt.VerifyTrustedHeader only the header and
// section geometry are checked; cnfrt.VerifyChecksum also verifies all
// section checksums. cnfrt.VerifyUntrusted copies the file to the heap,
// unmaps it and validates every reference, so arbitrary input is safe to
// read; the returned snapshot is then not memory-mapped.
//
// String getters of memory-mapped snapshots return copies. The mapping is
// released by Close or, failing that, when the snapshot becomes unreachable.
func MapPodFile(path string, mode cnfrt.VerifyMode) (*PodSnapshot, error) {
	m, err := unsafemmap.Open(path)
	if err != nil {
		return nil, err
	}
	if mode >= cnfrt.VerifyUntrusted {
		var data []byte
		err := unsafemmap.FaultSafe(func() error {
			data = cnfrt.AlignedCopy(m.Bytes())
			return nil
		})
		if cerr := m.Close(); err == nil {
			err = cerr
		}
		if err != nil {
			return nil, err
		}
		return trackPodSnapshot(loadPodSnapshot(data, mode))
	}
	var s *PodSnapshot
	err = unsafemmap.FaultSafe(func() (err error) {
		s, err = loadPodSnapshot(m.Bytes(), mode)
		return err
	})
	if err != nil {
		m.Close()
		return nil, err
	}
	mapped := m.IsMapped()
	s.mapping, s.isMmap, s.cloneStrs = m, mapped, mapped
	unsafemmap.AttachCleanup(s, m)
	return trackSharedPodSnapshot(s, nil)
}

// UnmarshalPodSnapshot decodes a .cnf image. Tables and strings of the result alias
// data, which must not be modified while the snapshot is in use, except with
// cnfrt.VerifyUntrusted, which validates an aligned private copy.
func UnmarshalPodSnapshot(data []byte, mode cnfrt.VerifyMode) (*PodSnapshot, error) {
	if mode >= cnfrt.VerifyUntrusted {
		return trackPodSnapshot(loadPodSnapshot(cnfrt.AlignedCopy(data), mode))
	}
	return trackSharedPodSnapshot(loadPodSnapshot(data, mode))
}

func loadPodSnapshot(data []byte, mode cnfrt.VerifyMode) (*PodSnapshot, error) {
	h, infos, err := cnfrt.ParseHeader(data, mode, SchemaHashPod)
	if err != nil {
		return nil, err
	}
	return buildPodSnapshot(data, h, infos, mode)
}

// buildPodSnapshot assembles a snapshot from the parsed sections of an image.
func buildPodSnapshot(data []byte, h cnfrt.Header, infos []cnfrt.SectionInfo, mode cnfrt.VerifyMode) (*PodSnapshot, error) {
	var err error
	s := &PodSnapshot{flags: h.Flags, seed: h.HashSeed, rootTable: h.RootTable, rootID: h.RootID}
	for _, in := range infos {
		switch {
		case in.Kind == cnfrt.SectionTable && in.Tag == 0:
			s.nodesPod, err = unsafemmap.Cast[flatPod](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 0:
			s.pool0, err = unsafemmap.Cast[flatKVStringStringMap](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 1:
			s.pool1, err = unsafemmap.Cast[flatContainer](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 2:
			s.pool2, err = unsafemmap.Cast[flatCondition](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 3:
			s.pool3, err = unsafemmap.Cast[cnfrt.Span32](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 4:
			s.pool4, err = unsafemmap.Cast[flatContainerPort](data, in)
		case in.Kind == cnfrt.SectionStrBlob && in.Tag == 0:
			s.strBlob = unsafemmap.String(data, in)
		case in.Kind == cnfrt.SectionExt && in.Tag == 0:
			s.locEntries, s.zoned, err = cnfrt.DecodeExt(cnfrt.SectionData(data, in))
			s.locs = (&cnfrt.LocTable{Entries: s.locEntries}).Locations()
		default:
			err = fmt.Errorf("%w: unexpected section kind %d tag %d", cnfrt.ErrCorruptHeader, in.Kind, in.Tag)
		}
		if err != nil {
			return nil, err
		}
	}
	switch s.rootTable {
	case 0:
		if s.rootID == 0 || uint64(s.rootID) > uint64(len(s.nodesPod)) {
			return nil, fmt.Errorf("%w: root ID %d", cnfrt.ErrBoundsViolation, s.rootID)
		}
	default:
		return nil, fmt.Errorf("%w: root table %d", cnfrt.ErrSchemaMismatch, s.rootTable)
	}
	if mode >= cnfrt.VerifyUntrusted {
		if err := s.validate(); err != nil {
			return nil, err
		}
	}
	return s, nil
}

// CompactPod is a 16-byte immutable value holding a complete frozen Pod in a
// single string, so a map or slice of CompactPod values contains one pointer per
// value. Scalar, string, time and address fields of the root are read
// directly at constant offsets without allocating; everything else is
// reachable through View.
//
// Layout (slim format 0x03): a flags byte, the root's single 112-byte flat
// record, the string blob offset, optional dictToken / ext / seed headers,
// the 64-bit schema hash, a section presence bitmask, unsigned varint
// counts for non-empty sections, payloads ordered by descending alignment
// (8, 4, 2, 1), and a trailing 4-byte CRC32C.
type CompactPod struct {
	cnfRaw string
}

var compactPodSlimSpecs = [7]cnfrt.SlimSectionSpec{
	{Kind: cnfrt.SectionPool, ElemAlign: 8, Tag: 2, ElemSize: 32},
	{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 0, ElemSize: 16},
	{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 1, ElemSize: 64},
	{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 3, ElemSize: 8},
	{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 4, ElemSize: 20},
	{Kind: cnfrt.SectionStrBlob, ElemAlign: 1, Tag: 0, ElemSize: 1},
	{Kind: cnfrt.SectionExt, ElemAlign: 1, Tag: 0, ElemSize: 1},
}

// SchemaHashCNF implements cnfrt.SchemaHasher.
func (CompactPod) SchemaHashCNF() uint64 { return SchemaHashPod }

// PackPod freezes src (as FreezePod does) into a CompactPod.
func PackPod(src *Pod, opts ...cnfrt.FreezeOption) (CompactPod, error) {
	return packPod(cnfrt.ModeDAG, src, opts)
}

// PackTreePod freezes src as a tree (as FreezeTreePod does) into a CompactPod.
func PackTreePod(src *Pod, opts ...cnfrt.FreezeOption) (CompactPod, error) {
	return packPod(cnfrt.ModeTree, src, opts)
}

// PackCyclicPod freezes src permitting directed cycles (as FreezeCyclicPod
// does) into a CompactPod.
func PackCyclicPod(src *Pod, opts ...cnfrt.FreezeOption) (CompactPod, error) {
	return packPod(cnfrt.ModeCyclic, src, opts)
}

// packPod freezes src into the pooled scratch snapshot of a freezer and
// encodes it, so that the only allocation is the encoded value itself.
func packPod(mode cnfrt.FreezeMode, src *Pod, opts []cnfrt.FreezeOption) (c CompactPod, err error) {
	if src == nil {
		return CompactPod{}, cnfrt.ErrNilRoot
	}
	if mode != cnfrt.ModeTree {
		cnfrt.Escape(src)
	}
	f := podFreezerPool.Get().(*podFreezer)
	defer func() {
		cnfrt.Recover(recover(), &err)
		if err != nil {
			c = CompactPod{}
		}
		f.reset()
		podFreezerPool.Put(f)
	}()
	f.b.Init(mode, 1, opts...)
	f.scratch = true
	f.b.ReuseStrBuf(f.strBuf)
	f.mn0(src)
	f.allocate()
	id := f.en0(src)
	f.finish()
	runtime.KeepAlive(src)
	if id != 1 {
		return CompactPod{}, fmt.Errorf("%w: unexpected compact root ID %d", cnfrt.ErrBoundsViolation, id)
	}
	s := f.s
	var secBuf [7]cnfrt.Section
	secs := secBuf[:0]
	if len(s.pool0) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 0, Count: uint32(len(s.pool0)), Data: cnfrt.ViewSliceLE(s.pool0)})
	}
	if len(s.pool1) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 1, Count: uint32(len(s.pool1)), Data: cnfrt.ViewSliceLE(s.pool1)})
	}
	if len(s.pool2) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 8, Tag: 2, Count: uint32(len(s.pool2)), Data: cnfrt.ViewSliceLE(s.pool2)})
	}
	if len(s.pool3) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 3, Count: uint32(len(s.pool3)), Data: cnfrt.ViewSliceLE(s.pool3)})
	}
	if len(s.pool4) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 4, Count: uint32(len(s.pool4)), Data: cnfrt.ViewSliceLE(s.pool4)})
	}
	if len(s.strBlob) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionStrBlob, ElemAlign: 1, Count: uint32(len(s.strBlob)), Data: cnfrt.UnsafeStringBytes(s.strBlob)})
	}
	if ext := cnfrt.EncodeExt(s.locEntries, s.zoned); ext != nil {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionExt, ElemAlign: 1, Count: uint32(len(ext)), Data: ext})
	}
	var flags uint8
	var dictToken uint64
	if s.flags&cnfrt.FlagHasDict != 0 {
		flags |= cnfrt.SlimFlagDict
		dictToken = s.dict.Token()
	}
	if s.flags&cnfrt.FlagCyclicAllowed != 0 {
		flags |= cnfrt.SlimFlagCyclic
	}
	buf, err := cnfrt.AppendSlimCompact(nil, flags, cnfrt.ViewSliceLE(s.nodesPod[:1]), dictToken, s.seed, SchemaHashPod, compactPodSlimSpecs[:], secs)
	f.strBuf = f.b.StrBuf()
	if err != nil {
		return CompactPod{}, err
	}
	return CompactPod{cnfRaw: cnfrt.UnsafeSealBytes(buf)}, nil
}

// BorrowCompactPod validates the compact prefix of raw and returns a CompactPod that
// aliases raw without copying. It is intended for zero-copy reads inside
// callbacks such as SlabMap.Borrow and FrozenMap.Borrow; the returned value
// must not be retained beyond the lifetime of raw.
func BorrowCompactPod(raw string) (CompactPod, error) {
	s, err := cnfrt.CheckSlimCompactString(raw, 113, SchemaHashPod)
	return CompactPod{cnfRaw: s}, err
}

// BorrowCompactPodBytes is BorrowCompactPod for a byte slice, without copying. The
// returned CompactPod aliases raw: it is valid only while raw is neither
// modified nor reused, typically for the duration of a SlabMap.Borrow
// callback, and must not be retained beyond it. Use ParseCompactPod on a copy
// to keep a value.
func BorrowCompactPodBytes(raw []byte) (CompactPod, error) {
	s, err := cnfrt.CheckSlimCompactBytes(raw, 113, SchemaHashPod)
	return CompactPod{cnfRaw: s}, err
}

// ParseCompactPod checks raw (as produced by Raw) and returns it as a CompactPod. The
// embedded image is verified according to mode. With cnfrt.VerifyUntrusted
// a value that references a cnfrt.Dict is rejected with
// cnfrt.ErrDictRequired unless that Dict is passed with cnfrt.AllowDict.
func ParseCompactPod(raw string, mode cnfrt.VerifyMode, opts ...cnfrt.ParseOption) (CompactPod, error) {
	c := CompactPod{cnfRaw: raw}
	if _, err := c.cnfLoad(mode, true, cnfrt.AllowedDict(opts)); err != nil {
		return CompactPod{}, err
	}
	return c, nil
}

// cnfCheck verifies the structure of the compact prefix (version, size,
// schema hash, dictionary registration and the offsets used by direct
// getters).
func (c CompactPod) cnfCheck() error {
	return cnfrt.CheckSlimCompactPrefix(c.cnfRaw, 113, SchemaHashPod)
}

func (c CompactPod) cnfU32(off int) uint32 {
	return binary.LittleEndian.Uint32([]byte(c.cnfRaw[off : off+4]))
}

func (c CompactPod) cnfExt() string {
	s := c.cnfRaw
	if len(s) < 125 || s[0]&cnfrt.SlimFlagExt == 0 {
		return ""
	}
	p := 117
	if s[0]&cnfrt.SlimFlagDict != 0 {
		p += cnfrt.SlimDictTokenSize
	}
	h := s[p : p+8]
	off := int(binary.LittleEndian.Uint32([]byte(h[0:4])))
	l := int(binary.LittleEndian.Uint32([]byte(h[4:8])))
	return s[off : off+l]
}

func (c CompactPod) cnfTime(off int) time.Time {
	b := c.cnfRaw[off : off+16]
	sec := int64(binary.LittleEndian.Uint64([]byte(b[0:8])))
	meta := binary.LittleEndian.Uint64([]byte(b[8:16]))
	if (meta>>30)&3 == cnfrt.LocUTC {
		return time.Unix(sec, int64(meta&0x3fffffff)).UTC()
	}
	return cnfrt.DecodeCompactTime(sec, meta, c.cnfExt())
}

func (c CompactPod) cnfAddr(off int) netip.Addr {
	f := cnfrt.CompactFlatAddr(c.cnfRaw, off)
	if f.Kind != cnfrt.AddrV6Zoned {
		return cnfrt.DecodeAddr(f, nil)
	}
	return cnfrt.DecodeCompactAddr(f, c.cnfExt())
}

func (c CompactPod) cnfLoad(mode cnfrt.VerifyMode, checkCRC bool, allow *cnfrt.Dict) (*PodSnapshot, error) {
	data := cnfrt.UnsafeStringBytes(c.cnfRaw)
	if mode >= cnfrt.VerifyUntrusted {
		data = cnfrt.AlignedCopy(data)
	}
	var infoBuf [7]cnfrt.SectionInfo
	h, dict, infos, err := cnfrt.ParseSlimCompact(data, 112, SchemaHashPod, 0, compactPodSlimSpecs[:], mode, checkCRC, allow, infoBuf[:0])
	if err != nil {
		return nil, err
	}
	s := &PodSnapshot{flags: h.Flags, seed: h.HashSeed, rootTable: h.RootTable, rootID: h.RootID, dict: dict, dictStrs: dict.Chunks()}
	if err := cnfrt.DecodeSliceLE(s.inlineRootPod[:], data[1:113]); err != nil {
		return nil, err
	}
	s.nodesPod = s.inlineRootPod[:]
	for _, in := range infos {
		switch {
		case in.Kind == cnfrt.SectionPool && in.Tag == 0:
			s.pool0, err = unsafemmap.Cast[flatKVStringStringMap](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 1:
			s.pool1, err = unsafemmap.Cast[flatContainer](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 2:
			s.pool2, err = unsafemmap.Cast[flatCondition](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 3:
			s.pool3, err = unsafemmap.Cast[cnfrt.Span32](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 4:
			s.pool4, err = unsafemmap.Cast[flatContainerPort](data, in)
		case in.Kind == cnfrt.SectionStrBlob && in.Tag == 0:
			s.strBlob = unsafemmap.String(data, in)
		case in.Kind == cnfrt.SectionExt && in.Tag == 0:
			s.locEntries, s.zoned, err = cnfrt.DecodeExt(cnfrt.SectionData(data, in))
			if err == nil {
				s.locs = (&cnfrt.LocTable{Entries: s.locEntries}).Locations()
			}
		default:
			err = fmt.Errorf("%w: unexpected section kind %d tag %d", cnfrt.ErrCorruptHeader, in.Kind, in.Tag)
		}
		if err != nil {
			return nil, err
		}
	}
	if mode >= cnfrt.VerifyUntrusted {
		if err := s.validate(); err != nil {
			return nil, err
		}
	}
	return s, nil
}

// IsZero reports whether c is the zero value.
func (c CompactPod) IsZero() bool { return c.cnfRaw == "" }

// UsesDict reports whether c stores any strings in a process-local cnfrt.Dict.
func (c CompactPod) UsesDict() bool { return len(c.cnfRaw) > 0 && c.cnfRaw[0]&cnfrt.SlimFlagDict != 0 }

// Detach returns a self-contained CompactPod with all dictionary strings
// materialized into its local string blob. If c does not use a dictionary,
// Detach returns c. By default the result keeps the hash seed of c
// (DefaultSeed unless c carries an explicit seed) and time.Local, so
// detaching the same value twice yields identical bytes; caller opts
// override those defaults except that WithDict is always cleared so the
// result never references a cnfrt.Dict. It returns cnfrt.ErrUnknownDict
// if the dictionary of c has been closed.
func (c CompactPod) Detach(opts ...cnfrt.FreezeOption) (CompactPod, error) {
	if !c.UsesDict() {
		return c, nil
	}
	v, err := c.Unpack()
	if err != nil || v == nil {
		return CompactPod{}, err
	}
	merged := make([]cnfrt.FreezeOption, 0, len(opts)+3)
	merged = append(merged, cnfrt.WithHashSeed(cnfrt.SlimCompactSeed(c.cnfRaw, 113)), cnfrt.WithPreserveLocal())
	merged = append(merged, opts...)
	merged = append(merged, cnfrt.WithDict(nil))
	mode := cnfrt.ModeDAG
	if c.cnfRaw[0]&cnfrt.SlimFlagCyclic != 0 {
		mode = cnfrt.ModeCyclic
	}
	return packPod(mode, v, merged)
}

// Raw returns the encoded value. It can be stored and later passed to
// ParseCompactPod.
func (c CompactPod) Raw() string { return c.cnfRaw }

// Equal reports whether c and o hold identical encodings.
func (c CompactPod) Equal(o CompactPod) bool { return c.cnfRaw == o.cnfRaw }

// View returns a view of the root over the embedded image. The image is
// not copied, but a snapshot header is allocated; the direct getters of
// CompactPod do not allocate. View panics if c is corrupt or references a closed
// cnfrt.Dict (use TryView to get an error instead), and returns the zero
// view for the zero value.
func (c CompactPod) View() PodView {
	if c.cnfRaw == "" {
		return PodView{}
	}
	s, err := c.cnfLoad(cnfrt.VerifyTrustedHeader, false, nil)
	if err != nil {
		panic(err)
	}
	return s.view0(s.rootID)
}

// TryView is like View but returns an error instead of panicking:
// cnfrt.ErrUnknownDict if c references a closed cnfrt.Dict, or a header
// error if c is corrupt.
func (c CompactPod) TryView() (PodView, error) {
	if c.cnfRaw == "" {
		return PodView{}, nil
	}
	if err := c.cnfCheck(); err != nil {
		return PodView{}, err
	}
	s, err := c.cnfLoad(cnfrt.VerifyTrustedHeader, false, nil)
	if err != nil {
		return PodView{}, err
	}
	return s.view0(s.rootID), nil
}

// Snapshot loads the embedded image as a snapshot, verified according to
// mode; see ParseCompactPod for the options.
func (c CompactPod) Snapshot(mode cnfrt.VerifyMode, opts ...cnfrt.ParseOption) (*PodSnapshot, error) {
	return c.cnfLoad(mode, true, cnfrt.AllowedDict(opts))
}

// Unpack rebuilds the original Pod. It returns cnfrt.ErrUnknownDict if c
// references a closed cnfrt.Dict.
func (c CompactPod) Unpack() (*Pod, error) {
	if c.cnfRaw == "" {
		return nil, nil
	}
	s, err := c.Snapshot(cnfrt.VerifyTrustedHeader)
	if err != nil {
		return nil, err
	}
	return s.view0(s.rootID).Unfreeze()
}

// SizeCNF implements cnfrt.SelfCodec.
func (c CompactPod) SizeCNF() int { return len(c.cnfRaw) }

// AppendCNF implements cnfrt.SelfCodec.
func (c CompactPod) AppendCNF(dst []byte) []byte { return append(dst, c.cnfRaw...) }

// DecodeCNF implements cnfrt.SelfDecoder. It checks the compact prefix;
// use ParseCompactPod to verify the embedded image as well. src is retained.
func (c *CompactPod) DecodeCNF(src string) error {
	s, err := cnfrt.CheckSlimCompactString(src, 113, SchemaHashPod)
	if err == nil {
		c.cnfRaw = s
	}
	return err
}

// CodecCNF implements cnfrt.CodecProvider. Maps such as cnfrt.FrozenMap and
// cnfrt.SlabMap use the returned codec for CompactPod values by default.
func (CompactPod) CodecCNF() cnfrt.Codec[CompactPod] { return compactPodCodec{} }

// compactPodCodec is the cnfrt.Codec of CompactPod. It also implements
// cnfrt.UntrustedValidator, verifying the embedded image completely and
// rejecting values that reference a cnfrt.Dict, and cnfrt.AlignedCodec,
// so that stored values keep their image 8-byte aligned.
type compactPodCodec struct{}

func (compactPodCodec) Size(c CompactPod) int { return len(c.cnfRaw) }

func (compactPodCodec) Append(dst []byte, c CompactPod) []byte { return append(dst, c.cnfRaw...) }

func (compactPodCodec) Decode(src string) (CompactPod, error) {
	s, err := cnfrt.CheckSlimCompactString(src, 113, SchemaHashPod)
	return CompactPod{cnfRaw: s}, err
}

func (compactPodCodec) ValidateUntrusted(src string) error {
	if src == "" {
		return nil
	}
	_, err := ParseCompactPod(src, cnfrt.VerifyUntrusted)
	return err
}

func (compactPodCodec) AlignCNF() int { return 8 }

// Namespace returns the Namespace field of the root without allocating.
func (c CompactPod) Namespace() string {
	s := c.cnfRaw
	if len(s) < 117 {
		return ""
	}
	o, l := cnfrt.U32S(s[17:]), cnfrt.U32S(s[21:])
	if o >= cnfrt.DictSpanBit {
		if l == 0 {
			return ""
		}
		return cnfrt.ResolveDictSpan(s, 117, o, l)
	}
	i := int(cnfrt.U32S(s[113:])) + int(o)
	return s[i : i+int(l)]
}

// NamespaceEquals reports whether the Namespace field equals v without allocating.
func (c CompactPod) NamespaceEquals(v string) bool {
	s := c.cnfRaw
	if len(s) < 117 {
		return v == ""
	}
	o, l := cnfrt.U32S(s[17:]), cnfrt.U32S(s[21:])
	if o >= cnfrt.DictSpanBit {
		if l == 0 {
			return v == ""
		}
		return cnfrt.ResolveDictSpan(s, 117, o, l) == v
	}
	i := int(cnfrt.U32S(s[113:])) + int(o)
	return s[i:i+int(l)] == v
}

// NamespaceLen returns the length of the Namespace field without allocating.
func (c CompactPod) NamespaceLen() int {
	if c.cnfRaw == "" {
		return 0
	}
	return int(c.cnfU32(21))
}

