// Priority returns the Priority field of the root and whether it is set.
func (c CompactPod) Priority() (int32, bool) {
	if c.cnfRaw == "" {
		var zero int32
		return zero, false
	}
	if !(c.cnfRaw[106]&(1<<0) != 0) {
		var zero int32
		return zero, false
	}
	return int32(binary.LittleEndian.Uint32([]byte(c.cnfRaw[81:85]))), true
}
